package domain

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"time"

	"github.com/google/uuid"
)

// ErrNotUUIDv7 is returned when an identifier does not carry a timestamp.
var ErrNotUUIDv7 = errors.New("identifier is not a UUIDv7")

// NewID returns a UUIDv7 for the current time.
func NewID() uuid.UUID { return NewIDAt(time.Now()) }

// NewIDAt returns a UUIDv7 whose timestamp is t, truncated to the millisecond.
//
// Identifiers are generated by the application, never by the database:
// messages and events are partitioned by time, and the partition key is
// derived from the identifier (see IDTime). A lookup by id alone can then
// target a single partition.
func NewIDAt(t time.Time) uuid.UUID {
	var u uuid.UUID
	ms := uint64(t.UnixMilli()) //nolint:gosec // dates before 1970 are not a use case
	var ts [8]byte
	binary.BigEndian.PutUint64(ts[:], ms)
	copy(u[0:6], ts[2:8])
	// crypto/rand.Read never fails on supported platforms (Go 1.24+).
	_, _ = rand.Read(u[6:])
	u[6] = (u[6] & 0x0f) | 0x70 // version 7
	u[8] = (u[8] & 0x3f) | 0x80 // RFC 9562 variant
	return u
}

// IDTime extracts the millisecond timestamp of a UUIDv7. It is the value
// stored in the partition key column (messages.created_at, events.occurred_at
// rounded to the millisecond for the id).
func IDTime(id uuid.UUID) (time.Time, error) {
	if id.Version() != 7 || id.Variant() != uuid.RFC4122 {
		return time.Time{}, ErrNotUUIDv7
	}
	var ts [8]byte
	copy(ts[2:8], id[0:6])
	ms := binary.BigEndian.Uint64(ts[:])
	return time.UnixMilli(int64(ms)).UTC(), nil //nolint:gosec // 48 bits always fit
}

// CompactID renders an identifier as 32 lowercase hex digits, the form used
// inside email addresses and Message-IDs, where dashes add nothing.
func CompactID(id uuid.UUID) string { return hex.EncodeToString(id[:]) }

// ParseCompactID is the inverse of CompactID. It also accepts the dashed form.
func ParseCompactID(s string) (uuid.UUID, error) {
	if len(s) != 32 && len(s) != 36 {
		return uuid.Nil, errors.New("invalid identifier length")
	}
	return uuid.Parse(s)
}
